\choice
  {$26$}
  {$17$}
  {$150$}
  {\True $144$}
\loigiai{
Số kết quả có thể xảy ra khi chọn độc lập ba món đồ là $6 \cdot 3 \cdot 8 = 144$.
}
\end{ex}

